var r={en:`Policy checks were bypassed; retrieved text is connected to tool execution and the orchestrator can call external services directly.`,ua:`Перевірки політик обійдені; знайдений текст веде до виконання інструментів, а оркестратор напряму викликає зовнішні сервіси.`};var a={en:[`Remove api→orchestrator bypass and untrusted retrieval→toolrunner path.`,`Remove orchestrator→external shortcut and restore api→policy.`,`Explain least-privilege tools and a malicious-document test.`],ua:[`Прибери api→orchestrator та недовірений retrieval→toolrunner.`,`Прибери orchestrator→external і віднови api→policy.`,`Поясни мінімальні права інструментів і тест шкідливого документа.`]};var o=[{en:`The orchestrator cannot bypass policy or approval gates.`,ua:`Оркестратор не обходить політики та погодження.`},{en:`Retrieved text cannot directly initiate an external action.`,ua:`Знайдений текст не може напряму запускати зовнішню дію.`}];var n={remove:[`api->policy`],add:[{from:`api`,to:`orchestrator`,kind:`sync`,label:`Intentional defect / Навмисна помилка`},{from:`retrieval`,to:`toolrunner`,kind:`sync`,label:`Intentional defect / Навмисна помилка`},{from:`orchestrator`,to:`external`,kind:`sync`,label:`Intentional defect / Навмисна помилка`}]};var c={scenario:r,tasks:a,checks:o,mutations:n};export{o as checks,c as default,n as mutations,r as scenario,a as tasks};